var s=e=>`<mi>${e}</mi>`,i=e=>`<mo>${e}</mo>`,r=(e,o)=>`<msub>${e}<mtext>${o}</mtext></msub>`,t={kind:"fluid",window:!0,forces:!0},a={kind:"abdomen"},n={kind:"course",reading:"asc",from:{preset:"cirr-decomp",params:{diuretics:!1},days:120,ramp:{albumin:[2.8,2.4]}},event:{params:{albumin:2.74},action:{kind:"paracentesis",mL:5100}},wait:14,after:28,then:[{name:"Diuretics",params:{diuretics:!0}},{name:"Diuretics + TIPS",params:{diuretics:!0,tips:{on:!0}}}],words:{event:"LVP",before:"Tense ascites",start:"Treatment starts",rise:"Refills",axis:"Weeks after LVP",label:"Ascites, liters",title:"Ascites after LVP",short:"After LVP"}},l={id:"ascites",level:"advanced",title:"Ascites: why it forms and how it is treated",minutes:18,summary:"How ascites forms in the sinusoids, what diagnostic paracentesis shows, and what each treatment does: large-volume paracentesis with albumin, diuretics and TIPS.",sections:[["Where ascites forms",["Ascites"]],["Diagnostic paracentesis",["Diagnostic paracentesis","Protein-rich ascites","Telling them apart"]],["Treating it",["Tense ascites","Large-volume paracentesis","Two weeks later","Treatment","Refractory ascites","Complications","Summary"]]],objectives:["Explain how sinusoidal pressure and hepatic lymph flow produce ascites","Interpret the SAAG and ascitic total protein, and distinguish cirrhosis, heart failure and Budd\u2013Chiari syndrome by diagnostic paracentesis","Give albumin correctly with large-volume paracentesis (LVP)","Use diuretics and TIPS for recurrent ascites, and define refractory ascites"],checks:[["What SAAG points to portal hypertension?","\u22651.1 g/dL."],["A high SAAG with an ascitic total protein \u22652.5 g/dL. Where is the problem?","Post-hepatic or cardiac: Budd\u2013Chiari syndrome or heart failure. The sinusoidal fenestrae are still open and let protein through."],["How much albumin is given with large-volume paracentesis?","6 to 8 g per liter of ascites removed, when >5 L is removed."],["When is ascites called refractory?","It recurs within 4 weeks of LVP despite maximum diuretic doses and sodium restriction, or diuretics cannot be given because of AKI, hyponatremia or hyperkalemia."],["Ten days after a 6 L paracentesis with albumin, tense ascites has reaccumulated on full-dose diuretics. What has not changed?","The portal pressure: paracentesis removes the fluid, not its cause. Ascites that recurs on full-dose diuretics is refractory, and TIPS is the next step to consider."]],slides:[{id:"start",terms:{"space of Disse":"sinusoid:disse",lymphatics:"sinusoid:lymph"},glow:["sinusoid:lumen"],preset:"csph",cam:"sinusoid",scales:{lobule:{glow:["lobule:sinusoid"]},anatomy:{cam:"fit"}},tool:t,data:"tiles",tiles:["sin","asc"],key:["sin"],kicker:"Ascites",site:"sin",title:"Ascites starts in the sinusoids",vignette:"A 55-year-old woman with MASH cirrhosis comes for a routine visit. She feels well and has no ascites. Her platelets are 90,000/\xB5L, and EGD shows small esophageal varices.",line:"Sinusoidal pressure drives plasma into the space of Disse. Hepatic lymphatics drain it until filtration exceeds their capacity.",notes:"Ascites in portal hypertension is mostly lymph, from the liver and, to a lesser degree, the intestine. Sinusoidal pressure drives plasma through the fenestrated sinusoidal endothelium into the space of Disse, and the hepatic lymphatics return it to the blood through the thoracic duct. Hepatic lymph flow can rise many-fold; once it exceeds lymphatic capacity, lymph weeps from the liver surface into the peritoneal cavity. In this case there is clinically significant portal hypertension (CSPH), and the lymphatics still keep up. Ascites can develop once the HVPG is \u226510 mmHg, the CSPH threshold, and the risk rises with the gradient.",ask:["What drains the sinusoidal filtrate before ascites forms?","The hepatic lymphatics, to the thoracic duct."]},{id:"lymph",terms:{lymphatics:"lobule:lymph","portal tracts":"lobule:triad"},cam:"lobule",scales:{sinusoid:{},anatomy:{cam:"fit"}},layers:["lymph"],tool:t,data:"tiles",tiles:["sin","asc"],key:["sin"],delta:"start",kicker:"Ascites",site:"sin",title:"Lymph leaves the liver along the portal tracts",line:"At a sinusoidal pressure of {sin}, the lymphatics along the portal tracts drain almost all the filtrate, so almost no ascites forms. Their capacity is limited.",notes:"Plasma filtered into the space of Disse flows toward the portal tracts, countercurrent to sinusoidal blood flow, and enters lymphatics that run with the portal vein branches to the hilum, then to the cisterna chyli and the thoracic duct. A smaller share leaves along the hepatic veins and beneath the capsule. The liver produces a quarter to a half of total body lymph, and hepatic lymph flow rises with sinusoidal pressure. The lymphatics dilate and carry many times their usual flow before they are overwhelmed; only then does lymph weep from the liver surface into the peritoneal cavity. In the data card the lymphatics drain almost all the lymph produced, about 10 mL/day leaks and there is no reserve, so any further rise in sinusoidal pressure will exceed lymphatic capacity.",ask:["Where does the sinusoidal filtrate go before ascites forms?","Through the space of Disse to lymphatics in the portal tracts, then to the thoracic duct."]},{id:"fill",days:60,ramp:{cirrhosis:[.6,.85],albumin:[4,2.8]},lapse:{seconds:9},cam:"fit",scales:{lobule:{glow:["lobule:sinusoid"]},sinusoid:{}},glow:["liver"],mark:{organ:"ascites",label:"Ascites {asc}"},tool:{kind:"flowtime",clock:"days",lines:["sin","asc"],keepTiles:!0,title:"Sinusoids and ascites over two months"},data:"tiles",tiles:["sin","asc"],key:["asc"],delta:"start",kicker:"Ascites",site:"sin",title:"Ascites builds over two months",line:"As fibrosis advances, sinusoidal pressure rises and lymph production exceeds lymphatic capacity. Ascites accumulates in the peritoneal cavity, and renal sodium and water retention keeps replacing it.",notes:"The model generates ascites from sinusoidal pressure and serum albumin; it does not model the kidneys. The time-lapse runs the model's disease clock: cirrhosis advances and serum albumin falls from 4.0 to 2.8 g/dL over 60 days, without diuretics. Sinusoidal pressure rises from about 17 to 25 mmHg, hepatic lymph exceeds lymphatic capacity and the ascites reaches several liters. The chart in the card follows sinusoidal pressure and ascites volume day by day; the next slide shows the fluid balance. In patients, splanchnic vasodilation lowers the effective arterial blood volume, and the kidneys retain sodium and water through the renin\u2013angiotensin\u2013aldosterone system, the sympathetic nervous system and vasopressin. High sinusoidal pressure puts the fluid in the peritoneal cavity; renal sodium and water retention keeps replacing it. Treatment: dietary sodium restriction, spironolactone with furosemide, large-volume paracentesis with albumin, TIPS.",ask:["Which hormone system drives sodium retention in cirrhotic ascites, and which drug blocks it?","Renin\u2013angiotensin\u2013aldosterone; spironolactone."]},{id:"overrun",terms:{lymphatics:"lobule:lymph","portal tracts":"lobule:triad"},cam:"lobule",layers:["lymph"],data:"tiles",tiles:["sin","asc"],key:["asc"],delta:"start",kicker:"Ascites",site:"sin",title:"When the lymphatics are overrun, lymph weeps from the liver",line:"At a sinusoidal pressure of {sin}, the lymphatics along the portal tracts carry many times their usual flow and still fall behind. The rest weeps from the liver surface.",notes:"The lymphatics along the portal tracts dilate and carry many times their usual flow before they are overwhelmed. Past that point the excess lymph weeps from the liver surface into the peritoneal cavity, and the ascites in the data card builds. Compare the first lymph slide, where the same lymphatics drained almost all the filtrate.",ask:["What happens to the lymph that the portal-tract lymphatics cannot carry?","It weeps from the liver surface into the peritoneal cavity."]},{id:"balance",glow:["liver"],cam:"fit",tool:t,data:"tiles",tiles:["sin","asc"],key:["asc"],delta:"start",kicker:"Ascites",site:"sin",title:"Lymph that exceeds lymphatic capacity accumulates as ascites",line:"At two months, hepatic lymph production exceeds lymphatic capacity. The net leak minus peritoneal reabsorption adds to the ascites every day.",notes:"The same patient as the slide before, held at two months. The first tile shows lymph production (hepatic and intestinal) against lymphatic capacity; the leak beyond that capacity is the amber part of its gauge. Peritoneal reabsorption returns part of that leak, and the difference is the daily accumulation of ascites, the value under the tiles. The second tile shows the net filtration pressure across the sinusoidal wall: the hydrostatic pressure driving fluid out minus the oncotic pressure of plasma protein. These are the model's own terms.",ask:["Why does ascites keep accumulating despite peritoneal reabsorption?","The leak beyond lymphatic capacity exceeds peritoneal reabsorption, so the difference accumulates each day."]},{id:"saag",preset:"csph",days:60,ramp:{cirrhosis:[.6,.85],albumin:[4,2.8]},cam:"fit",tool:{kind:"abdomen"},data:"tiles",tiles:["saag","tp"],key:["saag"],kicker:"Diagnostic paracentesis",site:"sin",title:"A SAAG \u22651.1 g/dL identifies portal hypertension",eq:[s("SAAG")+i("=")+r(s("Albumin"),"serum")+i("\u2212")+r(s("Albumin"),"ascites")],line:"On diagnostic paracentesis the serum\u2013ascites albumin gradient (SAAG) is {saag}. A SAAG \u22651.1 g/dL indicates portal hypertension as the cause.",notes:"Source: AASLD 2021. Diagnostic paracentesis is done for new-onset ascites and for every patient with ascites admitted to the hospital (30 to 60 mL from the left lower quadrant; routine correction of the INR or platelet count is not needed). The SAAG uses serum and ascitic fluid albumin measured on the same day. A SAAG \u22651.1 g/dL identifies portal hypertension as the cause with about 97% accuracy, whatever the cause of the portal hypertension. A SAAG <1.1 g/dL points to peritoneal disease or a very low serum albumin: malignancy, tuberculosis, pancreatitis, nephrotic syndrome. Send a cell count with differential (an ascitic PMN count >250/mm\xB3 is spontaneous bacterial peritonitis), total protein, and cultures inoculated into blood culture bottles at the bedside. Cirrhotic ascites has a total protein <2.5 g/dL, because sinusoidal capillarization closes the fenestrae and lays down a basement membrane. An ascitic total protein <1.5 g/dL reflects low opsonic activity and a higher risk of spontaneous bacterial peritonitis (SBP), so antibiotic prophylaxis is considered.",ask:["The SAAG is 0.8 g/dL. Is portal hypertension the cause?","No: a SAAG <1.1 g/dL means portal hypertension is not the cause. Look for peritoneal disease or a very low serum albumin."]},{id:"walls",visual:"walls",kicker:"Protein-rich ascites",title:"Open sinusoidal fenestrae let protein into the ascites",line:"A continuous splanchnic capillary retains protein. A congested sinusoid keeps its fenestrae open, so ascites in heart failure and Budd\u2013Chiari syndrome is protein-rich. In cirrhosis, capillarization closes the fenestrae.",notes:"An intestinal capillary has a continuous endothelium on a basement membrane, so plasma protein stays in the vessel and the filtrate is protein-poor. The normal hepatic sinusoid has fenestrae and no basement membrane, so protein crosses freely into the space of Disse and hepatic lymph has nearly the protein content of plasma. In cirrhosis the sinusoid is capillarized: the fenestrae close and a basement membrane forms, so the lymph and the ascites become protein-poor. In heart failure and early Budd\u2013Chiari syndrome the sinusoids are congested but not yet fibrotic, so the fenestrae stay open and the ascites is protein-rich.",ask:["Why is ascitic total protein high in heart failure and low in cirrhosis?","The congested sinusoid still has open fenestrae that let protein through; in cirrhosis, capillarization has closed them and laid down a basement membrane."]},{id:"hf",terms:{lymph:"sinusoid:lymph",sinusoid:"sinusoid:lumen"},preset:"rhf",cam:"sinusoid",data:"tiles",tiles:["saag","tp"],key:["tp"],kicker:"Protein-rich ascites",site:"cardiac",title:"Heart failure gives high-SAAG, high-protein ascites",vignette:"A 74-year-old man with ischemic cardiomyopathy and severe TR has a swollen abdomen and leg edema. His JVP is elevated to the earlobes, and his liver tests are only mildly abnormal.",line:"The sinusoid wall is still fenestrated, so congestion drives protein-rich lymph into the peritoneal cavity: SAAG {saag}, >1.1 g/dL, and total protein {tp}, >2.5 g/dL.",notes:"In heart failure and constrictive pericarditis the sinusoids are congested but not fibrotic: the fenestrae stay open, so hepatic lymph has nearly the protein content of plasma. The ascites has a high SAAG (portal hypertension of cardiac origin) and a total protein \u22652.5 g/dL. An elevated JVP and a high BNP point to the heart.",ask:["Ascites with a SAAG of 1.5 g/dL and a total protein of 3.8 g/dL. What do you examine next?","The heart: the JVP, an echocardiogram, BNP."]},{id:"bc",terms:["hv","sin"],preset:"budd-chiari",cam:"hepatic",labels:["RHV","RA"],mark:{edges:["RHV_IVC","MHV_IVC","LHV_IVC"],label:"Hepatic vein thrombosis",free:!0},tool:{kind:"doppler",vessel:"RHV_IVC"},data:"tiles",tiles:["saag","tp"],key:["tp"],kicker:"Protein-rich ascites",site:"post",title:"Budd\u2013Chiari syndrome gives high-SAAG, high-protein ascites",vignette:"A 26-year-old woman, 3 months postpartum, has had RUQ pain for 2 months and now has tense ascites. Her liver is large and tender.",line:"Resistance in the hepatic veins congests a liver that is not yet fibrotic. Its sinusoids are still fenestrated, so the SAAG is high and the total protein \u22652.5 g/dL.",notes:"Hepatic venous outflow obstruction gives the same high-SAAG, high-protein ascites as heart failure, but with a normal JVP. Over months the congested liver can become fibrotic and capillarized, and the total protein falls toward the cirrhotic range. Ascites with abdominal pain and hepatomegaly, in a patient with a myeloproliferative neoplasm or in pregnancy, calls for Doppler ultrasound of the hepatic veins.",ask:["High-SAAG, high-protein ascites and a normal JVP. Where do you look?","At the hepatic veins and the IVC, for Budd\u2013Chiari syndrome (Doppler ultrasound)."]},{id:"map",visual:"quadrant",of:[{id:"fill",name:"Cirrhosis"},{id:"hf",name:"Heart failure"},{id:"bc",name:"Budd\u2013Chiari"}],kicker:"Telling them apart",title:"SAAG and total protein locate the cause of ascites",line:"The SAAG shows whether portal hypertension is the cause. The ascitic total protein shows whether the sinusoids are capillarized or still permeable.",notes:"Read the SAAG first: \u22651.1 g/dL indicates portal hypertension. Then the total protein: <2.5 g/dL fits cirrhosis (capillarized sinusoids); \u22652.5 g/dL with a high SAAG fits heart failure or early Budd\u2013Chiari syndrome (open, congested sinusoids). A low SAAG with a high protein means peritoneal disease: peritoneal carcinomatosis, tuberculous peritonitis, pancreatic ascites. A low SAAG with a low protein is rare: nephrotic syndrome. Portal vein thrombosis and presinusoidal disease have no point here, because they rarely cause ascites: the sinusoids lie downstream of the resistance at near-normal pressure (see Portal vein clots and Presinusoidal portal hypertension). The points are the model's patients.",ask:["SAAG 0.6 g/dL, total protein 4.2 g/dL and weight loss. What is likely, and what next?","Peritoneal carcinomatosis or tuberculous peritonitis: cytology, adenosine deaminase, peritoneal biopsy."]},{id:"tense",preset:"cirr-decomp",params:{diuretics:!1},days:120,ramp:{albumin:[2.8,2.4]},cam:"fit",terms:{"renal veins":"lrv"},tool:a,data:"tiles",tiles:["asc","rpp"],key:["asc"],kicker:"Tense ascites",site:"sin",title:"Grade 3 ascites raises the intra-abdominal pressure",vignette:"A 61-year-old man with alcohol-associated cirrhosis stopped his diuretics 4 months ago. He now has tense ascites and orthopnea. His serum albumin is 2.4 g/dL.",line:"Tense ascites raises the intra-abdominal pressure (IAP), which compresses the renal veins and lowers the renal perfusion pressure.",notes:"Decompensated cirrhosis off diuretics for four months, with a falling serum albumin; about 5 L of ascites. Tense ascites raises the IAP, which lowers renal perfusion, splints the diaphragm and raises the variceal pressure. Dyspnea, early satiety and an umbilical hernia are common. Grade 3 ascites is treated first with large-volume paracentesis (LVP).",ask:["Name two effects of tense ascites outside the abdomen.","Dyspnea from a splinted diaphragm, and lower renal perfusion."]},{id:"lvp",action:{kind:"paracentesis",mL:5100},params:{albumin:2.74},cam:"fit",tool:a,data:"tiles",tiles:["asc","pv","salb"],key:["salb"],delta:"tense",kicker:"Large-volume paracentesis",site:"sin",title:"Large-volume paracentesis is given with albumin",line:"LVP drains the whole 5 L, and the portal pressure falls slightly. When >5 L is removed, give {6 to 8 g} of albumin per liter of ascites removed.",notes:'The model has no kidneys or renin: albumin here raises the serum albumin and the plasma oncotic pressure, and the ascites reaccumulates more slowly on "Ascites returns in two weeks". The model shows only the albumin: the serum albumin tile rises from 2.4 g/dL. It has no renin, serum sodium or renal function, which is where post-paracentesis circulatory dysfunction shows, and in patients the heart rate and blood pressure barely change, so there is no button to compare with and without albumin. For this LVP of just over 5 L, give about 30 to 40 g of 20% albumin, during or after the procedure; it prevents post-paracentesis circulatory dysfunction better than saline or synthetic colloids. For <5 L, albumin is optional. LVP can safely remove all the ascites in a single session of a few hours. Lowering the IAP lowers the portal and variceal pressure slightly. After removal of >5 L, splanchnic vasodilation worsens and the effective arterial blood volume falls over the following days: post-paracentesis circulatory dysfunction, with a rise in plasma renin, hyponatremia, AKI and faster reaccumulation of ascites.',ask:["Why give albumin rather than saline after a 5 L paracentesis, and how much?","It prevents post-paracentesis circulatory dysfunction better: less AKI, less hyponatremia, slower reaccumulation. About 30 to 40 g, at 6 to 8 g per liter of ascites removed."]},{id:"back",days:14,lapse:{seconds:7},cam:"fit",tool:{kind:"flowtime",clock:"days",lines:["pv","asc"],keepTiles:!0,title:"Portal pressure and ascites over two weeks"},data:"tiles",tiles:["asc","pv"],key:["asc"],delta:"tense",kicker:"Two weeks later",site:"sin",title:"Ascites returns in two weeks",line:"Sinusoidal pressure and renal sodium retention are unchanged, so without diuretics the ascites reaccumulates to {asc}.",notes:"The liver and intestine still produce more lymph than the lymphatics can drain. Sinusoidal pressure and renal sodium retention are unchanged, so lymph keeps weeping from the liver surface. He has had no diuretics.",ask:["The ascites has reaccumulated two weeks after LVP. Is this refractory ascites?","No: he has had no diuretics. Refractory ascites recurs within 4 weeks despite maximum diuretic doses and sodium restriction, or diuretics cannot be given."]},{id:"diuretics",params:{diuretics:!0},days:28,cam:"fit",tool:t,compare:[{label:"No diuretics",params:{diuretics:!1}},{label:"Diuretics",own:!0,params:{diuretics:!0}}],kicker:"Treatment",site:"sin",title:"Diuretics counter renal sodium retention",line:"Spironolactone with furosemide and a 2 g/day sodium restriction produce a natriuresis, so more ascites is reabsorbed and the volume stabilizes at {asc}.",notes:"The model has no kidneys, so here diuretics simply raise peritoneal reabsorption. Spironolactone 100 mg/day, with furosemide 40 mg/day for recurrent ascites; outside the US, EASL starts a first episode on spironolactone alone and adds furosemide if weight loss is slow or hyperkalemia develops. Both are increased in a 100:40 ratio to 400 and 160 mg/day. Sodium intake is about 2 g/day (5 g of salt); no fluid restriction unless the serum sodium is <125 mEq/L. Aim for a weight loss of up to 0.5 kg/day without peripheral edema, 1 kg/day with it. Reduce or stop for AKI, a serum sodium <125 mEq/L, hepatic encephalopathy or muscle cramps. Diuresis also concentrates the ascites, so its total protein rises.",ask:["Starting doses of spironolactone and furosemide?","Spironolactone 100 mg/day, with furosemide 40 mg/day for recurrent ascites (outside the US, EASL starts a first episode on spironolactone alone); both are increased in a 100:40 ratio to 400 and 160 mg/day."]},{id:"refractory",cam:"fit",data:"tiles",tiles:["asc","pv"],key:["asc"],tool:{kind:"criteria",title:"Refractory ascites",short:"Refractory",ticks:!1,lead:"Either one makes it refractory.",rows:["Recurs **within 4 weeks** on **maximum diuretic doses** and **sodium restriction**","Or **diuretics cannot be given** (AKI, hyponatremia, hyperkalemia)"]},kicker:"Refractory ascites",site:"sin",title:"Refractory ascites recurs despite maximum diuretic therapy",line:"Refractory ascites recurs within 4 weeks of LVP despite maximum diuretic doses, or diuretics cannot be given. Here the ascites stabilizes at {asc}, so it is not refractory.",notes:"Sources: the International Ascites Club definition of refractory ascites, which EASL and AASLD use; Baveno VIII 6.3 and 6.4 for TIPS. Refractory ascites recurs within 4 weeks of LVP despite maximum diuretic doses and sodium restriction, or diuretics cannot be given. Patients with recurrent or refractory ascites should be considered for a TIPS, with the TIPS and liver transplantation discussed together. Refractory means that maximum diuretic doses (spironolactone 400 mg/day and furosemide 160 mg/day) with about 2 g/day of sodium fail to control the ascites, or that diuretics must be stopped for AKI, a serum sodium <125 mEq/L, hyperkalemia or hepatic encephalopathy. Baveno VIII names refractory ascites without defining it, so the definition here is the International Ascites Club's.",ask:["Ascites recurs three weeks after LVP, on spironolactone 400 mg/day and furosemide 160 mg/day. What is the label, and what do you consider?","Refractory ascites. Consider a TIPS and discuss transplantation, if there is no recurrent hepatic encephalopathy, heart failure or severe pulmonary hypertension."]},{id:"path-asc",cam:"fit",tool:{kind:"path",of:"ascites",short:"Ascites path",patient:{tips:!0,lt:!0}},kicker:"Refractory ascites",site:"sin",title:"If his ascites were refractory, the algorithm would lead to a TIPS",line:"For recurrent or refractory ascites the algorithm starts with a TIPS, with liver transplantation discussed alongside. The other branches are for a patient who cannot have a TIPS.",notes:"This is the Baveno VIII algorithm for recurrent or refractory ascites (statements 6.3 to 6.11), applied to this patient. Patients with recurrent or refractory ascites should be considered for a TIPS (6.3), and the TIPS and a liver transplant discussed together (6.4). Renal function is assessed and chronic kidney disease staged by eGFR first (6.9). To limit overshunting, with hepatic encephalopathy and heart failure, the stent may be dilated only to the smallest diameter that gives an adequate response (6.5), and dilated stepwise if the ascites does not improve (6.6). If a TIPS is not possible, or is not sufficient, long-term albumin may be considered (6.10). A transplant candidate proceeds to transplant evaluation; a patient who is not, and who cannot have a TIPS, may have a home drainage device, a tunneled peritoneal catheter or a low-flow pump, in place of repeated large-volume paracentesis (6.11). Here a TIPS is possible and he is a transplant candidate, so the highlighted path ends at the TIPS. The model has no transplant list and no drainage device, so only the TIPS is shown on the figure, on a later slide.",ask:["A patient with refractory ascites cannot have a TIPS and is not a transplant candidate. What does the algorithm offer?","Long-term albumin, and a home drainage device (a tunneled peritoneal catheter or a low-flow pump) instead of repeated large-volume paracentesis."]},{id:"complications",cam:"fit",data:"tiles",tiles:["asc","pv"],key:["asc"],cite:"Baveno VIII 5.9, 6.18, 6.19, 6.21, 6.22, 6.24",tool:{kind:"criteria",title:"Complications of ascites",short:"Complications",ticks:!1,lead:"Each has its own first step.",rows:["**SBP**: paracentesis on admission; antibiotics, albumin, then **prophylaxis**","**HRS-AKI**: **terlipressin** infusion with albumin (6.18, 6.19)","**Hyponatremia**: sodium is watched, most of all on terlipressin (5.9)","**Hepatic hydrothorax**: treat as ascites; a TIPS if refractory"]},kicker:"Complications",site:"sin",title:"Every patient with ascites is watched for four complications",line:"Perform a diagnostic paracentesis on every admission to exclude SBP. HRS-AKI calls for terlipressin with albumin. The model has no kidneys, infection or serum sodium, so this card lists them.",notes:"Spontaneous bacterial peritonitis: a diagnostic paracentesis in every patient admitted with decompensation, to exclude infection (Baveno VIII Table 3); antibiotics are started promptly and short-term albumin is given in SBP, in AKI above stage 1A and after large-volume paracentesis (Table 3). The ascitic PMN cut-off and the albumin dose for LVP are on the earlier slides. Hepatorenal syndrome with acute kidney injury (HRS-AKI): the card gives the treatment only; terlipressin with albumin is the treatment (Baveno VIII 6.18), preferably as a continuous infusion starting at 2 to 3 mg in 24 hours, which causes fewer adverse events than boluses (6.19), and norepinephrine is the alternative when terlipressin is unavailable, contraindicated or not tolerated (6.20); transplant evaluation follows. Serum sodium is monitored on terlipressin because of the risk of hyponatremia (5.9). After an episode of SBP, antibiotic prophylaxis should be considered to prevent a recurrence (6.21), and it is stopped if the patient recompensates (6.22). In further decompensation a PPI is withdrawn unless there is a clear indication (6.24). Hepatic hydrothorax, usually right-sided, is treated as ascites, with a TIPS when it is refractory; a chest tube is avoided. Nonselective beta-blockers are dose-reduced or stopped when the systolic pressure stays <90 mmHg or AKI develops. Any of these is a reason to consider liver transplantation. The model has no kidneys, no infection and no serum sodium, so none of these can be shown on the figure.",ask:["A man with ascites is admitted with confusion. What is the first test?","A diagnostic paracentesis, to exclude spontaneous bacterial peritonitis and other infection."]},{id:"frailty",cam:"fit",tool:a,data:"tiles",tiles:["asc"],key:["asc"],cite:"Baveno VIII 4.16, 4.17, 4.18",kicker:"Complications",site:"sin",title:"Frailty, sarcopenia and malnutrition shorten survival with ascites",line:"Frailty, malnutrition and sarcopenia shorten survival in decompensated cirrhosis. Every patient gets a nutritional assessment, an individual plan and counseling on regular exercise.",notes:"Baveno VIII 4.16: frailty, malnutrition, sarcopenia and myosteatosis affect survival in patients with decompensated cirrhosis, and they should be assessed with a standardized tool. 4.17: every patient with decompensated cirrhosis gets a structured nutritional assessment, an individual nutrition plan and counseling on regular physical activity. 4.18: when a patient is frail or sarcopenic, add targeted interventions to that counseling, because muscle mass and function can improve, and outcomes with them; whether they change the course of further decompensation is not yet known. The model has no muscle or diet, so the figure shows only the abdomen.",ask:["A man with ascites has lost muscle mass and weight. What does Baveno VIII advise?","A standardized frailty and nutrition assessment, an individual nutrition plan and exercise counseling, with targeted interventions if he is frail or sarcopenic (4.16 to 4.18)."]},{id:"path-hold",cam:"fit",tool:{kind:"path",of:"holdcarv",short:"Carvedilol path",patient:{held:!1,sbp:84,hrs:!0}},kicker:"Complications",site:"sin",title:"Carvedilol is dose-reduced or stopped for hypotension or HRS-AKI",line:"Suppose he is on carvedilol and develops HRS-AKI, with a systolic pressure of {84 mmHg}. The algorithm says dose-reduce or stop, and restart once both have resolved.",notes:"Baveno VIII 4.6: in decompensated cirrhosis carvedilol, or another nonselective beta-blocker, should be dose-reduced or discontinued when the blood pressure stays low (systolic below 90 mmHg or mean arterial pressure below 65 mmHg) and/or there is HRS-AKI. 4.7: it should be restarted and re-titrated once the HRS-AKI has resolved and/or the blood pressure has recovered. The algorithm is applied to a man on carvedilol with HRS-AKI and a systolic pressure of 84 mmHg, which is <90 mmHg, so the path ends at dose reduction or discontinuation. Either problem is enough. A patient whose carvedilol is already held and who still has either problem stays off it. The model has no kidneys and no systolic pressure, so these values are set for the case, not read from the model; the Kidney in cirrhosis talk shows the MAP and the renal perfusion pressure that carvedilol and hemorrhage change.",ask:["A man with ascites on carvedilol develops HRS-AKI. What do you do with the carvedilol, and when is it restarted?","Reduce the dose or stop it. Restart and re-titrate once the HRS-AKI has resolved and the pressure has recovered."]},{id:"tips",params:{tips:{on:!0}},days:28,lapse:{seconds:7},cam:"liver",tool:{kind:"flowtime",clock:"days",lines:["pv","asc"],keepTiles:!0,title:"Portal pressure and ascites over four weeks"},mark:{edges:["TIPS"],label:"Covered stent",kind:"treat"},data:"tiles",tiles:["asc","pv","he"],key:["asc","he"],delta:"tense",cite:"Baveno VIII 6.3, 6.5, 6.16; Bureau, Gastroenterology 2017",kicker:"Refractory ascites",site:"sin",title:"A TIPS can control refractory ascites",line:"A TIPS lowers the portal pressure gradient (PPG) to {ppg}, and here the ascites resolves over weeks. The cost is hepatic encephalopathy, so rifaximin is considered beforehand.",notes:"Sinusoidal pressure falls, so less lymph forms; in exchange, portal perfusion of the liver falls. In recurrent or refractory ascites, a covered TIPS improves survival over repeated paracentesis in selected patients (Baveno VIII 6.3). In the trial by Bureau et al (Gastroenterology 2017, 62 patients with recurrent ascites), 1-year transplant-free survival was 93% with a covered TIPS and 52% with LVP plus albumin; the stent is dilated only as far as needed (6.5). The usual contraindications are recurrent hepatic encephalopathy, heart failure, pulmonary hypertension and advanced liver failure. Before the procedure, the history of overt hepatic encephalopathy and its treatment are reviewed (6.14), a prior episode is not an absolute contraindication (6.15), and rifaximin should be considered to prevent hepatic encephalopathy (6.16, strong). The ascites resolves over weeks to months, with diuretics continued at first. The model resolves it faster. No target PPG is agreed for ascites; <12 mmHg is the target for variceal bleeding.",ask:["Name a contraindication to a TIPS for ascites.","Recurrent hepatic encephalopathy, heart failure, pulmonary hypertension or advanced liver failure."]},{id:"relation",cam:"fit",tool:n,kicker:"Summary",site:"sin",title:"Ascites reaccumulates after LVP unless it is treated",line:"LVP empties the abdomen, but the ascites is back to {asc@back} by week 2. Diuretics reduce it to {asc@diuretics} by week 6, and adding a TIPS clears it.",notes:"The chart follows the model's patient day by day. Day 0 is the LVP: 5 L removed with albumin, from the tense ascites after four months off diuretics. The gray line is the two weeks with no treatment: the ascites reaccumulates because sinusoidal pressure and renal sodium and water retention are unchanged. From week 2 each treatment starts from that same day: diuretics alone, and diuretics with a TIPS. The zones are the app's own grades (its data card uses them too): grade 1 \u22650.15 L, grade 2 \u22651.5 L, grade 3 \u22655 L; at the bedside the grade comes from the examination, not from the volume. The timing is the model's, not a patient's; the model has no kidneys, and the chart shows the order of events and the size of each effect. One model patient; real patients vary far more.",ask:["LVP emptied his abdomen, yet the ascites is back in two weeks. What did LVP leave unchanged?","The sinusoidal pressure that produces it. Diuretics remove what has formed; a TIPS lowers the pressure itself, and the ascites stays away."]},{id:"summary",visual:"table",cols:["asc","ppg","liver"],asc:!1,vs:"first",rowHead:"Step",of:[{id:"tense",kicker:"Baseline",title:"Tense ascites"},{id:"lvp",kicker:"LVP",title:"Paracentesis with albumin"},{id:"back",kicker:"No treatment",title:"Two weeks on"},{id:"diuretics",kicker:"Drugs",title:"Diuretics, 4 weeks"},{id:"tips",kicker:"Shunt",title:"TIPS, 4 weeks"}],kicker:"Summary",title:"What each ascites treatment does",line:"LVP empties the abdomen, but only diuretics or a TIPS prevent the ascites from returning.",notes:"LVP removes the ascites at once but leaves its cause; albumin protects the circulation; diuretics clear it more slowly and prevent recurrence; a TIPS clears it by lowering the sinusoidal pressure, at the cost of portal perfusion of the liver. Every patient with refractory ascites is also evaluated for liver transplantation. Avoid NSAIDs, ACE inhibitors and ARBs in ascites; long-term albumin is used in some centers for decompensated cirrhosis.",ask:["Which step acts on the mechanism rather than only the fluid?","A TIPS lowers the sinusoidal pressure and diuretics counter the sodium retention; LVP does neither. Only treating the liver disease removes the cause."]}]};export{l as a};
